INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1eb2e66e-4f7e-40b5-bf6c-d90fa7e822e4', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$11. óra: Összeszámlálási feladatok megoldása$q$, $q$Önálló feladatmegoldás rendszerezett felsorolással és faábrával.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "a236e9b0-1f07-4806-bfa5-d0e53a31cb76", "text": "Hányféleképpen rakhatunk sorba 4 különböző könyvet a polcon? (4*3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "a65c7891-4287-4b79-b055-58502ca3dd1f", "text": "Hány 3 jegyű szám képezhető a 7, 8, 9 számjegyekből ha mindegyiket csak egyszer használhatjuk fel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "00d43e54-ca84-4518-9873-8e4dff208389", "text": "Az ágrajz utolsó szintjén lévő levelek száma megadja az összes lehetséges kimenetelt.", "type": "true-false", "options": [{"id": "086fea9b-cf04-4ae9-ba85-402580263885", "text": "Igaz", "isCorrect": true}, {"id": "6565b978-a648-48be-9481-a10c46850e35", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "38e9a4fd-ac46-4950-82f1-45ae35d0aa63", "text": "Melyik állítás igaz a valószínűségi kísérletekre?", "type": "multiple-choice", "options": [{"id": "711597cd-105d-420c-abdd-ebe1b52a2c62", "text": "A lehetséges esetek száma a kedvező és kedvezőtlen esetek összege", "isCorrect": true}, {"id": "d6bf5e05-5da6-4193-bb8d-25e8fe98bb36", "text": "Mindig csak 1 eset lehetséges", "isCorrect": false}, {"id": "25d15c7c-f077-4ada-9a16-66b119f4c719", "text": "Sohasem lehet kiszámolni az esetek számát", "isCorrect": false}, {"id": "fff6286a-b9e0-47b3-999a-dcdf89b022d2", "text": "Csak páros szám lehet az eredmény", "isCorrect": false}], "timeLimit": 15}, {"id": "79faed7d-08af-4300-924f-838d6fb7a500", "text": "Hányféle kétgombócos fagyit választhatunk 3-féle ízből, ha két különböző ízt kérünk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "3ef3b8ec-d147-4a44-b807-d9a1f4dc8f82", "text": "Ha egy feldobott pénzérmét kétszer dobunk fel egymás után, a lehetséges kimenetelek száma 4.", "type": "true-false", "options": [{"id": "9a6e89ec-57f4-4490-8bb2-ce7f353d93d2", "text": "Igaz (FF, FI, IF, II)", "isCorrect": true}, {"id": "06082d8d-e209-4dfe-9922-492ad1925c54", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bd358e84-61df-428b-a7cb-1c9071f64348", "text": "Hány válaszlehetőség van egy 4 opciós feleletválasztós kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ecf786af-1d82-4e00-8b0a-eb2bfd0c349f', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$12. óra: Számonkérés$q$, $q$Az egész számok műveleteiből és az összeszámlálásból tanultak számonkérése (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "2d20f204-8927-431f-8754-b2e38e65abc6", "text": "1. Mennyi (-15) + (+20)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "2ed8c0ce-8f72-40d7-b532-a91799ce459d", "text": "2. Mennyi (-6) * (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "78e9ce88-364e-4345-8f71-04abe1326e81", "text": "3. Mennyi (-54) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "8ed74dc6-d78b-42d6-ab7f-2105d3bba2e7", "text": "4. Melyik szám abszolút értéke nagyobb: |-30| vagy |+20|?", "type": "multiple-choice", "options": [{"id": "3ce254ed-a0fb-4a4a-b31c-073a51ba4680", "text": "|-30|", "isCorrect": true}, {"id": "b504f73c-9cc1-4212-80ef-b76816f0883b", "text": "|+20|", "isCorrect": false}, {"id": "9b5d4e07-d80d-4d17-9685-408de6579cfb", "text": "Egyenlőek", "isCorrect": false}, {"id": "45a91138-ba7a-47c6-a01e-f8b67eff8f78", "text": "Egyik sem", "isCorrect": false}], "timeLimit": 15}, {"id": "be7fa38f-2c64-4154-ae88-ba4355bebf08", "text": "5. Mennyi (-3) * (-2) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}, {"id": "52bce2bd-c6cd-4dbd-8b5e-f7fc7b1c57fd", "text": "6. A negatív szám szorzása negatív számmal pozitív eredményt ad.", "type": "true-false", "options": [{"id": "577303d7-d542-4629-8556-b175b2811c16", "text": "Igaz", "isCorrect": true}, {"id": "67b55ba5-f4e0-4b68-b11e-789f6ca39d20", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7eacc635-3204-40fa-ab8b-2ea659f8c7b2", "text": "7. Hány különböző sorrendben ülhet le 3 gyerek egy padra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "bd8617b7-44da-44f4-ac84-df7d1f279075", "text": "8. Mennyi (-40) : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "0986d8ff-09d1-4e60-a173-a762a094e24f", "text": "9. A nullának nincs ellentettje (vagy önmaga az ellentettje).", "type": "true-false", "options": [{"id": "b0497c17-d143-4c2a-bdc2-de32b0fbc0fd", "text": "Igaz", "isCorrect": true}, {"id": "2bf31ed0-0afb-4e81-aa3f-1222e891823c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "02a06c4f-0d67-4c7d-bdb5-a503daa5e5ec", "text": "10. Mennyi (-10) + (-20) - (-15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7bf5d307-d80d-40c5-8bad-f26dc136c47e', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$13. óra: Osztó, többszörös$q$, $q$Osztó, többszörös fogalma, osztópárok meghatározása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "786232c1-3b77-4213-8759-024583b5e90a", "text": "Mit nevezünk egy 'a' természetes szám osztójának?", "type": "multiple-choice", "options": [{"id": "6f49d823-9c9c-4411-9864-5b6454e45738", "text": "Azt a 'b' számot, amellyel 'a'-t elosztva a maradék 0", "isCorrect": true}, {"id": "36ed34e6-d2d3-4a40-bf03-2473710d7518", "text": "Azt a számot, amit 'a'-hoz hozzáadunk", "isCorrect": false}, {"id": "ccbb9a3c-96da-4710-b2a8-d7f03bb1c18d", "text": "Azt a számot, ami nagyobb 'a'-nál", "isCorrect": false}, {"id": "29592db9-a7c7-4fab-93bb-d8ae4cecd919", "text": "Minden páratlan számot", "isCorrect": false}], "timeLimit": 15}, {"id": "2832d602-d294-4bfb-affd-435290f47e07", "text": "Az 1 minden természetes számnak osztója.", "type": "true-false", "options": [{"id": "31a61dee-4930-471b-9dd6-58939719d5d2", "text": "Igaz", "isCorrect": true}, {"id": "0e47b5f1-d74d-49c3-9180-f70f629ffaed", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "58438843-e989-4194-b39c-182dccc83b20", "text": "Hány osztója van a 12-nek? (1, 2, 3, 4, 6, 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "65283f46-2e7f-46b5-8564-2b8cb3270ae8", "text": "Melyik szám a 15 többszöröse az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "4d83e1db-3f60-4ec4-bd48-702ac6b5557f", "text": "45", "isCorrect": true}, {"id": "13913f27-683a-4088-be2b-16780d4b1de9", "text": "5", "isCorrect": false}, {"id": "c0c11d89-220a-45e3-9880-d1ec477d6d81", "text": "3", "isCorrect": false}, {"id": "d836145c-0259-4000-84d8-bc2a37bf3a36", "text": "10", "isCorrect": false}], "timeLimit": 15}, {"id": "8401b8f4-57f4-4369-8050-89eb6742b8ae", "text": "Minden számnak végtelen sok többszöröse van.", "type": "true-false", "options": [{"id": "b15e7a06-f924-4cbe-b4c2-43030e6f84f5", "text": "Igaz", "isCorrect": true}, {"id": "7b9c6958-ce42-4ce1-8c87-65736175a2f8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e729c1bc-2b9e-475d-91ae-822ea0c62977", "text": "Mi a 20 legkisebb pozitív osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "0c3259a5-308b-43bf-bda9-606b554221e0", "text": "Mi a 20 legnagyobb osztója önmagán kívül?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('da087565-8030-4e11-a995-c60dc0495259', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$14. óra: Számolás maradékokkal$q$, $q$Az osztási maradék fogalma, paritás vizsgálata, összeg maradéka.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "470681d1-acec-406c-910d-d9e7e37c6922", "text": "Mennyi a maradék, ha 23-at elosztjuk 5-tel? (23 = 4*5 + 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "f4b01cc7-9280-4db2-bc3b-1f891bfbab35", "text": "Egy számot 4-gyel elosztva a lehetséges maradékok: 0, 1, 2, 3.", "type": "true-false", "options": [{"id": "d3bdb9b9-e06e-4e86-81dd-5392ac7dcaa8", "text": "Igaz", "isCorrect": true}, {"id": "ceb903b0-d616-470c-9d6d-d713a96acc41", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dde55ed3-8959-4b97-9649-bb8e143677f5", "text": "Milyen maradékot ad 2-vel osztva minden páratlan szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "501340dd-91cb-45f0-a008-0c54cf658749", "text": "Két páratlan szám összege mindig páros szám.", "type": "true-false", "options": [{"id": "107cb20a-bdbf-4053-b27e-592c2911798d", "text": "Igaz (páratlan + páratlan = páros)", "isCorrect": true}, {"id": "50bfb038-5854-4038-a5a6-020b1c019a75", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8e404aef-2e77-4436-b183-ec86c5e6356b", "text": "Mennyi a maradék 37 : 10 esetén?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "648cb42c-79f0-489f-b843-9bc5dcbd33fe", "text": "Két páros szám szorzata mindig páros szám.", "type": "true-false", "options": [{"id": "96f7bfa9-b12d-4c34-96fd-75db2eb61a04", "text": "Igaz", "isCorrect": true}, {"id": "0c706e4a-70bd-44d9-9218-48b041cbb404", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "06f96e45-32fd-4bdb-9d2c-1fed8ae74ec3", "text": "Melyik szám ad 0 maradékot 3-mal osztva?", "type": "multiple-choice", "options": [{"id": "90b01560-31bf-4762-b686-1df35eec1c5c", "text": "15", "isCorrect": true}, {"id": "d0c24562-46c0-4039-97f9-f34bee6be832", "text": "16", "isCorrect": false}, {"id": "e4df31b2-24ba-4a56-aadb-282f196ac912", "text": "17", "isCorrect": false}, {"id": "5ceb08e9-50a2-498c-ae7e-36d99463c109", "text": "19", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9e74c59d-590c-4826-9ff2-2481ceec1b1d', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$15. óra: Hány osztója van?$q$, $q$Természetes számok csoportosítása osztóik száma alapján, prímek és összetett számok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "94289e53-78bf-4325-aabd-25617615ee5c", "text": "Hogyan nevezzük azokat a számokat, amelyeknek pontosan 2 osztójuk van (1 és önmaga)?", "type": "multiple-choice", "options": [{"id": "410f8bb5-3537-4c67-80fe-c4397b44cb4e", "text": "Prímszámok (prímek)", "isCorrect": true}, {"id": "9181f171-c362-495b-aa48-98ac33ee96e8", "text": "Összetett számok", "isCorrect": false}, {"id": "384207b8-0a65-4e90-aadc-2f3ab0a37a75", "text": "Páros számok", "isCorrect": false}, {"id": "637260ac-9d97-48ab-a539-d76486cc468c", "text": "Negatív számok", "isCorrect": false}], "timeLimit": 15}, {"id": "a170f725-2de8-4edf-839c-d7544531e6cb", "text": "Az 1 prímszám.", "type": "true-false", "options": [{"id": "12b08c5e-bb4e-4ae0-8b56-a8476b89456c", "text": "Igaz", "isCorrect": false}, {"id": "8eddafdf-eca6-480a-af38-239ea1a44158", "text": "Hamis (az 1 sem nem prím, sem nem összetett)", "isCorrect": true}], "timeLimit": 15}, {"id": "72e193b9-c44c-40ac-a070-88a633e23328", "text": "Melyik a legkisebb prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "79060c1f-7668-4819-abd7-c9c40a473bba", "text": "Melyik az egyetlen páros prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "ce8f246a-4498-4c70-a9be-6f9c439f9084", "text": "Azokat a számokat, amelyeknek 2-nél több osztójuk van, összetett számoknak nevezzük.", "type": "true-false", "options": [{"id": "033c8177-45fd-4bc6-a4b7-7342aa874e2e", "text": "Igaz", "isCorrect": true}, {"id": "fb643009-6545-40ae-858b-d6b0e090e6b3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "31e9d3c5-9969-40d4-aac3-a8a6d0ea9623", "text": "Hány osztója van a 7-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "ca7f30ab-d84d-4317-8058-5bf863a59991", "text": "Melyik prím az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "f3d0bf4a-cc51-4de1-9fc3-62613a04c839", "text": "13", "isCorrect": true}, {"id": "2ffabe91-1de7-4d4f-8817-834107e101f1", "text": "9", "isCorrect": false}, {"id": "025df910-f15f-42c0-83bc-ca99a21379f1", "text": "15", "isCorrect": false}, {"id": "d24b8d8a-aabc-4b15-918f-07be2f7589c3", "text": "21", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bac7aeed-d000-4e55-b72a-fe11ecead34e', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$16. óra: Feladatok az osztók számának meghatározására, számolás maradékokkal$q$, $q$Szöveges feladatok az osztókról és maradékokról.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "396e811d-d425-439d-b8a9-31df93e275ab", "text": "Hány osztója van a 9-nek? (1, 3, 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "f84a2c78-ba7a-4467-b9e2-7bd2106df8c5", "text": "A négyzetszámoknak páratlan számú osztójuk van.", "type": "true-false", "options": [{"id": "0e2f4f4a-3404-4c05-a5fe-a57ac4cee8db", "text": "Igaz (pl. 9-nek 3 osztója van: 1, 3, 9)", "isCorrect": true}, {"id": "e8d158f0-da4e-4ba8-bbbc-851893dff01d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4f1f2289-5f16-4025-9892-69bbdeab62f6", "text": "Ha 25 alma van és 4 gyerek között egyenlően elosztjuk, hány alma marad a kosárban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "bb139aff-d54d-45b9-aad1-cfc0c13d2568", "text": "Hány prímszám van 10 és 20 között? (11, 13, 17, 19)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "a326dcad-1bab-455d-bc1b-3b31be953226", "text": "Melyik szám összetett szám az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "7078662b-342f-44ba-921e-083a2dd1567c", "text": "27 (osztói: 1,3,9,27)", "isCorrect": true}, {"id": "e806dcbd-0c5f-4e26-8434-da2b0ff7946d", "text": "23", "isCorrect": false}, {"id": "5376f001-6cb8-41d4-88d5-7a3eb574d87b", "text": "29", "isCorrect": false}, {"id": "ebfcaf80-d482-4bd7-9c42-5818c08345de", "text": "31", "isCorrect": false}], "timeLimit": 15}, {"id": "90be42c9-13ce-4eb5-9533-6c3a3a4abfe3", "text": "Minden páratlan szám prímszám.", "type": "true-false", "options": [{"id": "7bb8d8b6-299c-4188-932e-7f36a772c081", "text": "Igaz", "isCorrect": false}, {"id": "a48faea8-259d-4aa5-a6a7-78539da76923", "text": "Hamis (pl. 9, 15, 21 nem prím)", "isCorrect": true}], "timeLimit": 15}, {"id": "34a1f767-a0cd-4f27-89a0-732f8080ee53", "text": "Mennyi a legkisebb kétjegyű prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5195341a-5f35-4464-856d-7ee745593e2e', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$17. óra: Oszthatóság 2-vel, 5-tel, 10-zel$q$, $q$Oszthatósági szabályok az utolsó számjegy alapján.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "ce70b230-38de-4756-9687-2a86b3af78df", "text": "Mikor osztható egy szám 2-vel?", "type": "multiple-choice", "options": [{"id": "e27efe50-d5e5-4f30-a3f8-217c8063b763", "text": "Ha az utolsó számjegye páros (0, 2, 4, 6, 8)", "isCorrect": true}, {"id": "da784ff6-5588-486e-995b-f62b76dfb506", "text": "Ha a számjegyek összege 2", "isCorrect": false}, {"id": "69c8c545-b88d-4fe9-bbd2-87f6ab3cfacf", "text": "Ha 5-re végződik", "isCorrect": false}, {"id": "4d7d972b-1f42-4368-b3b6-533722d65686", "text": "Minden szám osztható 2-vel", "isCorrect": false}], "timeLimit": 15}, {"id": "9d537cb2-aba6-46d8-b1ea-c5c2ca5a7d82", "text": "Mikor osztható egy szám 5-tel?", "type": "multiple-choice", "options": [{"id": "5287e157-1fcd-49ba-bb92-cc792c92f037", "text": "Ha az utolsó számjegye 0 vagy 5", "isCorrect": true}, {"id": "d166b732-26c3-4030-b603-6b7bbfeb8792", "text": "Ha 2-re végződik", "isCorrect": false}, {"id": "bd5b7167-f27c-460c-bd4b-eff05d05b8a6", "text": "Ha páratlan", "isCorrect": false}, {"id": "b481c0a9-563e-42cf-b54c-49524437639e", "text": "Ha a számjegyek összege 5", "isCorrect": false}], "timeLimit": 15}, {"id": "ddadae07-b523-48e4-8989-a3e55e03525f", "text": "Mikor osztható egy szám 10-zel?", "type": "multiple-choice", "options": [{"id": "02bce887-8823-4100-83ad-f6bf55f3fb5b", "text": "Ha az utolsó számjegye 0", "isCorrect": true}, {"id": "8fd0229d-7504-4e0a-840c-21e6dbf86420", "text": "Ha az utolsó számjegye 5", "isCorrect": false}, {"id": "607831be-5257-4f31-9f1d-b8dfd4a22f13", "text": "Ha páros", "isCorrect": false}, {"id": "2c958b49-aa82-4bb0-aa0f-feeb134933f4", "text": "H