INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4d46498d-0fc7-4ebd-87de-021f58acb751', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$18. óra: Oszthatóság 3-mal és 9-cel$q$, $q$A számjegyek összegén alapuló oszthatósági szabályok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "b033c902-3201-4bd8-8780-bd569c3dcd05", "text": "Mikor osztható egy szám 3-mal?", "type": "multiple-choice", "options": [{"id": "dced8fa6-fe80-47cd-a22a-11ca28387aa8", "text": "Ha a számjegyeinek összege osztható 3-mal", "isCorrect": true}, {"id": "fadc4daa-d9bf-4876-863f-8233abd97b25", "text": "Ha 3-ra végződik", "isCorrect": false}, {"id": "bf9d48ed-7577-4c51-b064-66741fdc6259", "text": "Ha páratlan", "isCorrect": false}, {"id": "e6553a63-3e13-4b62-a040-27a97228fa09", "text": "Ha az utolsó számjegye 3, 6 vagy 9", "isCorrect": false}], "timeLimit": 15}, {"id": "aa5ac2ec-b407-43ec-a84a-87a6403178fe", "text": "Mikor osztható egy szám 9-cel?", "type": "multiple-choice", "options": [{"id": "df54b1a6-3dc1-448c-af99-33f14dd92c18", "text": "Ha a számjegyeinek összege osztható 9-cel", "isCorrect": true}, {"id": "28271d95-e1e4-43c1-a760-9c6a9ef9d09d", "text": "Ha 9-re végződik", "isCorrect": false}, {"id": "ba528184-9dd7-4cf2-809c-0a4534e9dcfd", "text": "Ha 3-ra végződik", "isCorrect": false}, {"id": "ddaaeb30-59e9-419b-b7f1-7c2bbb2eea6c", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "c625ac99-58ee-463a-ba62-326b2fbdc43f", "text": "Mennyi a 243 számjegyeinek összege (2+4+3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "2167815b-5747-4e77-b2f2-de68ba7f6bf4", "text": "A 243 osztható 3-mal és 9-cel is.", "type": "true-false", "options": [{"id": "f71f6174-870c-446d-a5f0-0b4535bd6787", "text": "Igaz", "isCorrect": true}, {"id": "8be421d0-f2e8-4c15-b014-2b90dc415f9a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"i