INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4557e89c-5b99-4410-9499-ea85b2a95d9c', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$19. óra: Oszthatóság 4-gyel és 100-zal$q$, $q$Oszthatósági szabály az utolsó két számjegy alapján.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "25e17dc2-0b2f-4fb4-9338-0cb2bffd94a9", "text": "Mikor osztható egy szám 4-gyel?", "type": "multiple-choice", "options": [{"id": "48edb015-3f39-467e-9e74-b78f9cad6c3a", "text": "Ha az utolsó két számjegyéből képzett kétjegyű szám osztható 4-gyel (vagy 00)", "isCorrect": true}, {"id": "1d0a3302-9506-4e63-80ca-10bc40f47e7e", "text": "Ha 4-re végződik", "isCorrect": false}, {"id": "ec6e7720-8d6e-4146-9ca3-bd86669b9b00", "text": "Ha a számjegyek összege 4", "isCorrect": false}, {"id": "38477926-6ac5-4350-9276-a4f037d8e9ca", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "b3cf1bd9-ed70-4d83-8744-fe10aca7aea5", "text": "Mikor osztható egy szám 100-zal?", "type": "multiple-choice", "options": [{"id": "c6b45562-e610-4d55-a875-c1bbe6ed4629", "text": "Ha az utolsó két számjegye 00", "isCorrect": true}, {"id": "6467afa5-1b76-4b81-9bff-bb30cc07c0ca", "text": "Ha 100-ra végződik", "isCorrect": false}, {"id": "cc6a5633-9dad-4fc1-ac90-e3db8635752a", "text": "Ha 0-ra végződik", "isCorrect": false}, {"id": "5234b25f-34ca-4e74-916c-c13f096bac5f", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "4e83cf93-e51e-4408-bf2d-adffdd7a4865", "text": "A 316 osztható 4-gyel (mert 16 osztható 4-gyel).", "type": "true-false", "options": [{"id": "c5ad9033-93a1-45a5-a6a7-af00a28e60ca", "text": "Igaz", "isCorrect": true}, {"id": "3f78a35c-23a5-402d-9be1-7ebe45fd6d4b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4b7837d8-0006-4df3-b1db-8023c0fb02ee", "text": "A 7500 osztható 100-zal és 4-gyel is.", "type": "true-false", "options": [{"id": "36533d5f-3