INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('fbf4f57f-3b00-4b9f-b2ac-dffed9c7fc7a', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$20. óra: Összetett oszthatósági szabályok$q$, $q$Új oszthatósági szabályok alkotása (pl. 6-tal való oszthatóság).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "9fc8c8e6-d22b-4443-809d-5f6a22fea5c8", "text": "Mikor osztható egy szám 6-tal?", "type": "multiple-choice", "options": [{"id": "ccd58cf7-2876-4ab9-b408-61e9f827aca8", "text": "Ha 2-vel és 3-mal is osztható egyszerre (páros és a számjegyösszeg 3-mal osztható)", "isCorrect": true}, {"id": "c67d0f09-79a0-4875-b293-8b76c8e5fcdc", "text": "Ha 6-ra végződik", "isCorrect": false}, {"id": "712fa34a-fbb6-4fb0-8a5b-2103ff2d4e6c", "text": "Ha a számjegyek összege 6", "isCorrect": false}, {"id": "cd847ece-080a-4a60-b7cd-99a87816d133", "text": "Ha 12-vel osztható", "isCorrect": false}], "timeLimit": 15}, {"id": "ebf7ae6f-3cfb-442f-8705-eb32b596b48b", "text": "Mikor osztható egy szám 15-tel?", "type": "multiple-choice", "options": [{"id": "9529fcd3-adec-4409-809a-820d9b9ec75a", "text": "Ha 3-mal és 5-tel is osztható egyszerre", "isCorrect": true}, {"id": "aafc5d2f-2b44-4451-8a35-0cfb08b955ef", "text": "Ha 15-re végződik", "isCorrect": false}, {"id": "c2b94865-f937-409f-96ff-d10b66c04326", "text": "Ha páratlan", "isCorrect": false}, {"id": "1d646b31-ed42-4304-b810-5fbe3c3d79bf", "text": "Ha 5-tel osztható", "isCorrect": false}], "timeLimit": 15}, {"id": "8d9302c8-34a5-4518-83ae-6e649c459f53", "text": "A 132 osztható 6-tal (páros és 1+3+2=6).", "type": "true-false", "options": [{"id": "d029ce9d-bf0b-42a1-a080-1608ea89261e", "text": "Igaz", "isCorrect": true}, {"id": "c097bd2f-9d27-4d6c-b1df-305d07930634", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "27996e3c-6ac4-4b72-b886-00276c5229a4", "text": "A 45 osztható 15-tel.", "type": "true-false", "options": [{